// https://storybook.js.org/docs/7.0/preact/writing-stories/introduction
import type { Meta, StoryObj } from '@storybook/preact-vite';
import { Price, PriceProps } from '@adobe-commerce/elsie/components/Price';
import { expect, within } from 'storybook/test';

/**
 * Use Price components to display the cost of an item or service.
 */
const meta: Meta<PriceProps> = {
  title: 'Components/Price',
  component: Price,
  argTypes: {
    currency: {
      control: 'select',
      options: ['USD', 'EUR'],
    },
    locale: {
      control: 'select',
      options: ['en-US', 'fr-FR'],
    },
    variant: {
      description: 'Font variant',
      defaultValue: 'default',
      control: 'select',
      options: ['default', 'strikethrough'],
    },
    size: {
      control: 'select',
      options: ['small', 'medium', 'large'],
    },
    weight: {
      description: 'Font weight',
      defaultValue: 'bold',
      control: 'select',
      options: ['bold', 'normal'],
    },
    formatOptions: {
      control: { type: 'object' },
      defaultValue: {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
      },
    },
    amount: {
      description: 'Price amount',
      type: {
        name: 'number',
      },
    },
    sale: {
      description: 'Indicates a sale price',
      control: 'boolean',
    },
  },
};

export default meta;

type Story = StoryObj<PriceProps>;

/**
 * ```ts
 * import { Price } from '@adobe-commerce/elsie/components/Price';
 * ```
 */

export const Primary: Story = {
  args: {
    amount: 9.99,
    sale: false,
    size: 'small',
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await expect(await canvas.findByText('$9.99')).toBeVisible();
  },
};

export const SpecialDefault: Story = {
  args: {
    size: 'small',
  },
  render: (args) => (
    <div style="display: flex; flex-wrap:wrap; gap: 5px">
      <Price {...args} amount={59.99} variant={'strikethrough'} />
      <Price {...args} amount={55.99} variant={'default'} />
    </div>
  ),
};

export const HighContrast: Story = {
  args: {
    size: 'small',
  },
  render: (args) => (
    <div style="display: flex; flex-wrap:wrap; gap: 5px">
      <Price {...args} amount={59.99} variant={'strikethrough'} />
      <Price {...args} amount={55.99} variant={'default'} sale />
    </div>
  ),
};
